def Rfunc(x, terms=40):
    """Riemann's R function = sum_{n>=1} mu(n)/n * li(x^{1/n})."""
    s = mpmath.mpf(0)
    for n in range(1, terms + 1):
        m = int(mobius(n))
        if m == 0:
            continue
        s += mpmath.mpf(m) / n * mpmath.li(mpmath.mpf(x) ** (mpmath.mpf(1) / n))
    return s

